const enc=new TextEncoder();
class NBT{constructor(){this.a=[]}byte(v){this.a.push(v&255)}short(v){this.byte(v>>8);this.byte(v)}int(v){this.byte(v>>24);this.byte(v>>16);this.byte(v>>8);this.byte(v)}long(v){v=BigInt(v);for(let k=7;k>=0;k--)this.byte(Number((v>>BigInt(k*8))&255n))}str(v){const a=enc.encode(v);this.short(a.length);this.a.push(...a)}tag(t,name,fn){this.byte(t);this.str(name);fn()}compound(name,fn){this.tag(10,name,()=>{fn();this.byte(0)})}ints(name,a){this.tag(11,name,()=>{this.int(a.length);a.forEach(v=>this.int(v))})}emptyList(name){this.tag(9,name,()=>{this.byte(10);this.int(0)})}}
export function stateName(b){const p=Object.entries(b.properties||{});return b.id+(p.length?'['+p.map(([k,v])=>k+'='+v).join(',')+']':'')}
function paletteFor(p){const states=[{id:'minecraft:air',properties:{}}],lookup=new Map([['minecraft:air',0]]);for(const i of p.cells)if(i>=0){const b=p.palette[i],s=stateName(b);if(!lookup.has(s)){lookup.set(s,states.length);states.push(b)}}const ids=[];for(let y=0;y<p.height;y++)for(let x=0;x<p.width;x++){const i=p.cells[(p.height-y-1)*p.width+x];ids.push(i<0?0:lookup.get(stateName(p.palette[i])))}return {states,ids}}
export function schematicBytes(p){const {states,ids}=paletteFor(p),data=[];for(let v of ids){do{let b=v&127;v>>>=7;if(v)b|=128;data.push(b)}while(v)}const n=new NBT();n.compound('Schematic',()=>{n.tag(3,'Version',()=>n.int(2));n.tag(3,'DataVersion',()=>n.int(3700));n.tag(2,'Width',()=>n.short(p.width));n.tag(2,'Height',()=>n.short(p.height));n.tag(2,'Length',()=>n.short(1));n.ints('Offset',[0,0,0]);n.compound('Metadata',()=>n.tag(8,'Name',()=>n.str(p.name||'Blockloom build')));n.tag(3,'PaletteMax',()=>n.int(states.length));n.compound('Palette',()=>states.forEach((s,i)=>n.tag(3,stateName(s),()=>n.int(i))));n.tag(7,'BlockData',()=>{n.int(data.length);data.forEach(b=>n.byte(b))});n.emptyList('BlockEntities');n.emptyList('Entities')});return new Uint8Array(n.a)}
export function litematicBytes(p){const {states,ids}=paletteFor(p),bits=Math.max(2,Math.ceil(Math.log2(states.length))),words=Array(Math.ceil(ids.length*bits/64)).fill(0n),mask=(1n<<64n)-1n;ids.forEach((value,i)=>{const v=BigInt(value),bit=i*bits,w=Math.floor(bit/64),shift=bit%64;words[w]|=(v<<BigInt(shift))&mask;if(shift+bits>64)words[w+1]|=v>>BigInt(64-shift)});const n=new NBT(),int=(k,v)=>n.tag(3,k,()=>n.int(v)),str=(k,v)=>n.tag(8,k,()=>n.str(v)),vec=(k,x,y,z)=>n.compound(k,()=>{int('x',x);int('y',y);int('z',z)});n.compound('',()=>{int('Version',6);int('SubVersion',1);int('MinecraftDataVersion',3700);n.compound('Metadata',()=>{str('Name',p.name||'Blockloom build');str('Author','Blockloom');str('Description','Vertical image wall. Stand south, look north.');str('Software','Blockloom');int('RegionCount',1);int('TotalVolume',p.width*p.height);int('TotalBlocks',p.cells.filter(v=>v>=0).length);vec('EnclosingSize',p.width,p.height,1);n.tag(4,'TimeCreated',()=>n.long(p.created||Date.now()));n.tag(4,'TimeModified',()=>n.long(Date.now()));n.ints('PreviewImageData',[])});n.compound('Regions',()=>n.compound('Build',()=>{vec('Position',0,0,0);vec('Size',p.width,p.height,1);n.tag(9,'BlockStatePalette',()=>{n.byte(10);n.int(states.length);for(const b of states){str('Name',b.id);if(Object.keys(b.properties||{}).length)n.compound('Properties',()=>Object.entries(b.properties).forEach(([k,v])=>str(k,v)));n.byte(0)}});for(const k of ['Entities','TileEntities','PendingBlockTicks','PendingFluidTicks'])n.emptyList(k);n.tag(12,'BlockStates',()=>{n.int(words.length);words.forEach(v=>n.long(v))})}))});return new Uint8Array(n.a)}
async function gzip(bytes){return new Blob([await new Response(new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer()],{type:'application/octet-stream'})}
export const schematicBlob=p=>gzip(schematicBytes(p));export const litematicBlob=p=>gzip(litematicBytes(p));
export function csvText(p,translate=s=>s){const counts=new Map();p.cells.forEach(i=>{if(i>=0)counts.set(i,(counts.get(i)||0)+1)});return ['Block','Identifier','Count','Full stacks','Remainder','Full shulkers','Remaining stacks','Remaining blocks'].map(translate).join(',')+'\r\n'+[...counts].sort((a,b)=>b[1]-a[1]).map(([i,n])=>[translate(p.palette[i].name),p.palette[i].id,n,Math.floor(n/64),n%64,Math.floor(n/1728),Math.floor(n%1728/64),n%64].join(',')).join('\r\n')}
export function validateProject(p,blocks){if(!p||p.format!=='blockloom'||p.version!==1)throw Error('Not a supported Blockloom project.');if(!Number.isInteger(p.width)||!Number.isInteger(p.height)||p.width<1||p.height<1||p.width>256||p.height>256)throw Error('Invalid dimensions.');if(!Array.isArray(p.palette)||!p.palette.length||p.palette.length>512)throw Error('Invalid palette.');const known=new Map(blocks.map(b=>[b.id,b]));p.palette=p.palette.map(b=>{if(!known.has(b.id))throw Error('Unsupported block.');return known.get(b.id)});if(!Array.isArray(p.cells)||p.cells.length!==p.width*p.height||p.cells.some(i=>!Number.isInteger(i)||i< -1||i>=p.palette.length))throw Error('Invalid cells.');p.done=Array.isArray(p.done)?[...new Set(p.done.filter(i=>Number.isInteger(i)&&i>=0&&i<p.cells.length&&p.cells[i]>=0))]:[];p.collected=Array.isArray(p.collected)?p.collected.filter(s=>typeof s==='string'):[];p.name=String(p.name||'Imported build').slice(0,100);if(p.source&&(!/^data:image\/(png|jpeg|webp);base64,/.test(p.source)||p.source.length>12000000))throw Error('Invalid source image.');p.settings=p.settings&&typeof p.settings==='object'?p.settings:{};return p}
